/* JAH demo program — JAH-MOVFS-000001 */
/* Signature Dawn Reel ascii frame demo */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("ASCII FRAME DEMO — Signature Dawn Reel");
console.log("(text frames stand in for canvas frames; the page engine renders these on canvas)");
var W=40;
for(var f=0;f<4;f++){var x=(f*3)%(W-2);var line="";for(var i=0;i<W;i++){line+=(i===x?"O":(i===x+1?"o":"."));}console.log("f"+f+" "+line);}
console.log("4 frames rendered as text — page engine plays 96 frames at 12 fps on canvas.");

